// SPDX-License-Identifier: Apache-2.0
// Settings ▸ About: `licenses:get` and `licenses:open-folder`.
//
// - The four licence files ship in `resources/licenses/` next to app.asar (electron-builder
//   `extraResources`); dev and unpackaged runs read them from the project root.
// - THIRD_PARTY_NOTICES.md is parsed here (it is generated by scripts/dev/third-party-notices.mjs,
//   so its shape is fixed): the "Bundled outside npm metadata" section, the package table and
//   each package's licence text.
// - A missing file is null, never an error: the page says so instead.

import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { app, ipcMain, shell } from 'electron'
import type { InvokeChannel, InvokeRes, SendChannel } from '@shared/ipc'
import type { ThirdPartyPackage } from '@shared/types/licenses'
import { log } from '../log'

const COPYRIGHT = 'Copyright 2026 Augusto Henriques'

function licensesFolder(): string {
  return app.isPackaged ? join(process.resourcesPath, 'licenses') : app.getAppPath()
}

async function readText(name: string): Promise<string | null> {
  try {
    return (await readFile(join(licensesFolder(), name), 'utf8')).replace(/\r\n/g, '\n')
  } catch (err) {
    log('warn', 'licenses:read-failed', { name, err: err instanceof Error ? err.message : String(err) })
    return null
  }
}

/** The body of a `## <title>` section, up to the next `## ` heading outside a code fence. */
function section(md: string, title: string): string | null {
  const lines = md.split('\n')
  const start = lines.indexOf(`## ${title}`)
  if (start < 0) return null
  let fenced = false
  let end = start + 1
  for (; end < lines.length; end++) {
    if (lines[end]!.startsWith('```')) fenced = !fenced
    else if (!fenced && lines[end]!.startsWith('## ')) break
  }
  return lines
    .slice(start + 1, end)
    .join('\n')
    .trim()
}

function parseNotices(md: string): { bundled: string | null; packages: ThirdPartyPackage[] } {
  // `### name@version`, then the text in a ```text fence (or one line saying there is none).
  const texts = new Map<string, string | null>()
  let id: string | null = null
  let body: string[] | null = null
  for (const line of (section(md, 'Licence texts') ?? '').split('\n')) {
    if (body) {
      if (line === '```') {
        if (id) texts.set(id, body.join('\n'))
        body = null
      } else body.push(line)
    } else if (line.startsWith('### ')) {
      id = line.slice(4).trim()
      texts.set(id, null)
    } else if (line === '```text') body = []
  }
  const packages: ThirdPartyPackage[] = []
  for (const line of (section(md, 'npm packages') ?? '').split('\n')) {
    const cells = line.split('|').map((c) => c.trim())
    // | name | version | licence | repository |  →  ['', name, version, licence, repository, '']
    if (cells.length < 6 || cells[1] === 'Package' || /^-+$/.test(cells[1]!)) continue
    const [, name, version, license, repository] = cells as [string, string, string, string, string]
    packages.push({ name, version, license, repository, text: texts.get(`${name}@${version}`) ?? null })
  }
  return { bundled: section(md, 'Bundled outside npm metadata'), packages }
}

export function registerLicenses(): void {
  ipcMain.handle('licenses:get' satisfies InvokeChannel, async (): Promise<InvokeRes<'licenses:get'>> => {
    const [notice, models, licenseText, notices] = await Promise.all([
      readText('NOTICE'),
      readText('MODELS.md'),
      readText('LICENSE'),
      readText('THIRD_PARTY_NOTICES.md')
    ])
    const parsed = notices ? parseNotices(notices) : { bundled: null, packages: [] }
    return {
      version: app.getVersion(),
      license: 'Apache-2.0',
      copyright: COPYRIGHT,
      folder: licensesFolder(),
      notice,
      models,
      licenseText,
      ...parsed
    }
  })

  ipcMain.on('licenses:open-folder' satisfies SendChannel, () => {
    void shell.openPath(licensesFolder()).then((err) => {
      if (err) log('warn', 'licenses:open-folder-failed', { err })
    })
  })
}
